export type ErrorTypes =
  | 'TOKEN_EXPIRED'
  | 'REFRESH_EXPIRED'
  | 'NO_TOKEN'
  | 'INSUFFICIENT_PERMISSIONS';

export type MeData = {
  body?: never;
  path?: never;
  query?: never;
  url: '/auth/me';
};

export type MeErrors = {
  /**
   * Authentication failed
   */
  401: {
    message?: ErrorTypes;
    error?: 'Unauthorized';
    statusCode?: 401;
  };
  /**
   * Insufficient permissions
   */
  403: {
    message?: ErrorTypes;
    error?: 'Forbidden';
    statusCode?: 403;
  };
  /**
   * User not found
   */
  404: {
    message?: string;
    error?: 'Not Found';
    statusCode?: 404;
  };
};

export type MeError = MeErrors[keyof MeErrors];

export type MeResponses = {
  200: UserDto;
};

export type MeResponse = MeResponses[keyof MeResponses];

